@startuml

class Traveller {
  +name: string
  +companyName: string
  +address: string
  +travelPreferences: string[]
  +reliabilityRating: float
}

class CreditCard {
  +information: string
}

class SearchCriteria {
  +city: string
  +arrivalDate: date
  +departureDate: date
  +numberOfRooms: int
  +roomType: string
  +minimumHotelRating: int
  +maxCostPerNight: double
  +furtherPreferences: string[]
}

class PreliminaryBooking {
  +bookingIdentifier: string
  +price: double
  +cityArea: string
  +hotelRating: int
  +keyPreferences: string[]
}

class Booking {
  +cancellationDeadline: date
}

class PrePaidBooking extends Booking {
}

class PaidAtHotelBooking extends Booking {
}

class Hotel {
  +name: string
  +address: string
  +rating: int
}

class HotelChain {
  +name: string
}

class SpecialOffer {
  +price: double
}

class RoomType {
  +type: string
}

class Availability {
  +isFullyBooked: boolean
}

Traveller "1" -- "*" PreliminaryBooking : creates
Traveller "1" -- "*" Booking : makes
Traveller "1" -- "1" CreditCard : provides

PreliminaryBooking "1" -- "*" SpecialOffer : receives
Hotel "1" -- "*" SpecialOffer : provides

Hotel "1" -- "*" Booking : confirms
Hotel "1" -- "*" Availability : announces
Hotel "1" -- "*" RoomType : offers
Hotel "0..1" -- "1" HotelChain : run by
Hotel "1" -- "1" City : located in

City "1" -- "*" Hotel : contains

Booking "1" -- "1" Booking : can be cancelled

@enduml

